"""
Generic JSON Formatter for Messaging Apps
Formats ANY JSON output from a previous activity into clean,
readable messages for Slack, Webex, or plain text.

Works with any API response - not tied to any specific product.

SETUP:
  Script Input Variables:
    - raw_json       (String, Required)  - mapped from previous activity output
    - title          (String, Optional)  - custom title, defaults to "API Response"
    - max_items      (String, Optional)  - max list items to show, defaults to "25"
    - exclude_keys   (String, Optional)  - comma-separated keys to hide,
                                           e.g. "token,password,secret"

  Script Output Variables:
    - formatted_message  (String) - plain text formatted
    - slack_message      (String) - Slack mrkdwn formatted
    - webex_message      (String) - Webex markdown formatted
    - record_count       (String) - number of top-level items (for conditions)
    - status_value       (String) - extracted status if present (for conditions)
"""

import json
import sys


# ============================================================
# CONFIGURATION - Set defaults, override via input variables
# ============================================================

# Keys commonly used for status across various APIs
STATUS_KEYS = ["status", "ok", "success", "result", "error", "errorMessage",
               "state", "code", "statusCode", "status_code"]

# Keys to always exclude from output (secrets, tokens, etc.)
DEFAULT_EXCLUDE = {"token", "password", "secret", "apikey", "api_key",
                   "access_token", "refresh_token", "authorization",
                   "private_key", "signing_secret", "client_secret"}

# Keys that typically hold the main data payload
DATA_KEYS = ["response", "data", "result", "results", "payload",
             "items", "records", "entries", "body", "output", "content"]


# ============================================================
# HELPER FUNCTIONS
# ============================================================

def detect_status(data):
    """Extract status info from common API response patterns."""
    if not isinstance(data, dict):
        return None, None

    for key in STATUS_KEYS:
        if key in data:
            val = data[key]
            if isinstance(val, bool):
                return key, "Success" if val else "Failed"
            return key, str(val)
    return None, None


def detect_data_payload(data):
    """Find the main data payload in the response."""
    if not isinstance(data, dict):
        return data

    for key in DATA_KEYS:
        if key in data and isinstance(data[key], (dict, list)):
            return data[key]
    return data


def should_exclude(key, exclude_set):
    """Check if a key should be excluded from output."""
    return key.lower() in exclude_set


def format_key(key):
    """Convert snake_case or camelCase keys to readable labels."""
    # Handle camelCase
    result = ""
    for i, char in enumerate(key):
        if char.isupper() and i > 0:
            result += " "
        result += char
    # Handle snake_case and kebab-case
    result = result.replace("_", " ").replace("-", " ")
    # Title case
    return result.strip().title()


def format_value(value):
    """Format a single value for display."""
    if isinstance(value, bool):
        return "Yes" if value else "No"
    if value is None:
        return "N/A"
    if isinstance(value, list):
        if not value:
            return "None"
        if all(isinstance(i, (str, int, float)) for i in value):
            return ", ".join(str(v) for v in value)
        return f"({len(value)} items)"
    if isinstance(value, dict):
        if len(value) <= 3:
            parts = [f"{format_key(k)}: {format_value(v)}"
                     for k, v in value.items()]
            return " | ".join(parts)
        return f"({len(value)} fields)"
    return str(value)


def flatten_for_display(data, exclude_set, parent_key="", sep=" > ", depth=0,
                        max_depth=3):
    """Flatten nested structures for display, respecting depth limits."""
    if depth >= max_depth:
        return [(parent_key, format_value(data))]

    items = []
    if isinstance(data, dict):
        for k, v in data.items():
            if should_exclude(k, exclude_set):
                continue
            display_key = f"{parent_key}{sep}{format_key(k)}" if parent_key \
                else format_key(k)
            if isinstance(v, dict) and depth < max_depth - 1:
                items.extend(
                    flatten_for_display(v, exclude_set, display_key, sep,
                                       depth + 1, max_depth)
                )
            elif isinstance(v, list) and v and isinstance(v[0], dict):
                items.append((display_key, f"({len(v)} items - see below)"))
            else:
                items.append((display_key, format_value(v)))
    else:
        items.append((parent_key or "Value", format_value(data)))
    return items


def detect_table_data(data):
    """Detect if data is a list of uniform dicts (table-friendly)."""
    if not isinstance(data, list) or len(data) == 0:
        return False, [], []
    if not all(isinstance(item, dict) for item in data):
        return False, [], []

    # Get common keys across all items
    all_keys = set()
    for item in data:
        all_keys.update(item.keys())

    # Use key order from first item, then any extras
    ordered_keys = list(data[0].keys())
    for k in all_keys:
        if k not in ordered_keys:
            ordered_keys.append(k)

    return True, data, ordered_keys


# ============================================================
# PLAIN TEXT FORMATTER
# ============================================================

def format_plain(data, title, exclude_set, max_items):
    """Format any JSON data as plain readable text."""
    lines = []
    lines.append(f"{'=' * 55}")
    lines.append(f"  {title}")
    lines.append(f"{'=' * 55}")
    lines.append("")

    # Extract and show status
    status_key, status_val = detect_status(data)
    if status_key:
        lines.append(f"  Status: {status_val}")
        lines.append(f"  {'-' * 45}")
        lines.append("")

    # Get main payload
    payload = detect_data_payload(data)

    # Handle list of dicts (table format)
    if isinstance(payload, list):
        is_table, rows, columns = detect_table_data(payload)
    else:
        is_table, rows, columns = False, [], []

    if is_table:
        columns = [c for c in columns if not should_exclude(c, exclude_set)]
        display_rows = rows[:max_items]
        lines.append(f"  Records: {len(rows)}"
                      + (f" (showing first {max_items})"
                         if len(rows) > max_items else ""))
        lines.append(f"  {'-' * 45}")
        lines.append("")

        # Calculate column widths
        col_widths = {}
        for col in columns:
            header = format_key(col)
            max_w = len(header)
            for row in display_rows:
                val = format_value(row.get(col, ""))
                max_w = max(max_w, min(len(val), 40))
            col_widths[col] = max_w

        # Header
        header_line = "  " + "  ".join(
            f"{format_key(c):<{col_widths[c]}}" for c in columns
        )
        lines.append(header_line)
        lines.append("  " + "  ".join("-" * col_widths[c] for c in columns))

        # Rows
        for row in display_rows:
            row_line = "  " + "  ".join(
                f"{format_value(row.get(c, 'N/A')):<{col_widths[c]}}"
                for c in columns
            )
            lines.append(row_line)

        if len(rows) > max_items:
            lines.append(f"\n  ... and {len(rows) - max_items} more records")

    elif isinstance(payload, list):
        # Simple list
        lines.append(f"  Items: {len(payload)}")
        lines.append(f"  {'-' * 45}")
        for i, item in enumerate(payload[:max_items], 1):
            lines.append(f"  [{i}] {format_value(item)}")
        if len(payload) > max_items:
            lines.append(f"  ... and {len(payload) - max_items} more")

    elif isinstance(payload, dict):
        # Key-value display
        flat = flatten_for_display(payload, exclude_set)
        if flat:
            max_key_len = max((len(k) for k, v in flat), default=0)
            max_key_len = min(max_key_len, 35)
            for key, value in flat:
                lines.append(f"  {key:<{max_key_len}}  :  {value}")

        # Check for nested lists within the dict
        for k, v in payload.items():
            if isinstance(v, list) and v and isinstance(v[0], dict):
                lines.append("")
                lines.append(f"  --- {format_key(k)} ({len(v)} items) ---")
                is_sub_table, sub_rows, sub_cols = detect_table_data(v)
                if is_sub_table:
                    sub_cols = [c for c in sub_cols
                                if not should_exclude(c, exclude_set)]
                    for row in v[:max_items]:
                        parts = [f"{format_key(c)}: {format_value(row.get(c, ''))}"
                                 for c in sub_cols[:6]]
                        lines.append(f"    {' | '.join(parts)}")
    else:
        lines.append(f"  {format_value(payload)}")

    lines.append("")
    lines.append(f"{'=' * 55}")
    return "\n".join(lines)


# ============================================================
# SLACK FORMATTER
# ============================================================

def format_slack(data, title, exclude_set, max_items):
    """Format any JSON data as Slack mrkdwn."""
    lines = []
    lines.append(f"*{title}*")
    lines.append("")

    # Status
    status_key, status_val = detect_status(data)
    if status_key:
        is_ok = status_val.lower() in ("ok", "success", "true", "200", "201")
        emoji = ":white_check_mark:" if is_ok else ":x:"
        lines.append(f"{emoji} *Status:* `{status_val}`")
        lines.append("")

    payload = detect_data_payload(data)

    # Table data
    is_table = False
    if isinstance(payload, list):
        is_table, rows, columns = detect_table_data(payload)

    if is_table:
        columns = [c for c in columns if not should_exclude(c, exclude_set)]
        display_cols = columns[:8]  # Limit columns for readability
        display_rows = rows[:max_items]

        lines.append(f"*Records: {len(rows)}*"
                      + (f" _(showing first {max_items})_"
                         if len(rows) > max_items else ""))
        lines.append("```")

        # Header
        col_widths = {}
        for col in display_cols:
            header = format_key(col)
            max_w = len(header)
            for row in display_rows:
                val = format_value(row.get(col, ""))
                max_w = max(max_w, min(len(val), 30))
            col_widths[col] = max_w

        header_line = "  ".join(
            f"{format_key(c):<{col_widths[c]}}" for c in display_cols
        )
        lines.append(header_line)
        lines.append("  ".join("-" * col_widths[c] for c in display_cols))

        for row in display_rows:
            row_line = "  ".join(
                f"{format_value(row.get(c, 'N/A')):<{col_widths[c]}}"
                for c in display_cols
            )
            lines.append(row_line)

        lines.append("```")
        if len(rows) > max_items:
            lines.append(f"_... and {len(rows) - max_items} more records_")

    elif isinstance(payload, list):
        lines.append(f"*Items: {len(payload)}*")
        lines.append("```")
        for i, item in enumerate(payload[:max_items], 1):
            lines.append(f"[{i}] {format_value(item)}")
        lines.append("```")
        if len(payload) > max_items:
            lines.append(f"_... and {len(payload) - max_items} more_")

    elif isinstance(payload, dict):
        flat = flatten_for_display(payload, exclude_set)
        for key, value in flat:
            lines.append(f"• *{key}:* `{value}`")

        # Nested lists
        for k, v in payload.items():
            if isinstance(v, list) and v and isinstance(v[0], dict):
                lines.append("")
                lines.append(f"*{format_key(k)} ({len(v)} items):*")
                is_sub_table, sub_rows, sub_cols = detect_table_data(v)
                if is_sub_table:
                    sub_cols = [c for c in sub_cols
                                if not should_exclude(c, exclude_set)][:6]
                    lines.append("```")
                    for row in v[:max_items]:
                        parts = [f"{format_key(c)}: {format_value(row.get(c, ''))}"
                                 for c in sub_cols]
                        lines.append(f"  {' | '.join(parts)}")
                    lines.append("```")
    else:
        lines.append(f"`{format_value(payload)}`")

    return "\n".join(lines)


# ============================================================
# WEBEX FORMATTER
# ============================================================

def format_webex(data, title, exclude_set, max_items):
    """Format any JSON data as Webex markdown."""
    lines = []
    lines.append(f"## {title}")
    lines.append("")

    # Status
    status_key, status_val = detect_status(data)
    if status_key:
        is_ok = status_val.lower() in ("ok", "success", "true", "200", "201")
        emoji = "✅" if is_ok else "❌"
        lines.append(f"{emoji} **Status:** `{status_val}`")
        lines.append("")

    payload = detect_data_payload(data)

    # Table data
    is_table = False
    if isinstance(payload, list):
        is_table, rows, columns = detect_table_data(payload)

    if is_table:
        columns = [c for c in columns if not should_exclude(c, exclude_set)]
        display_cols = columns[:8]
        display_rows = rows[:max_items]

        lines.append(f"**Records: {len(rows)}**"
                      + (f" *(showing first {max_items})*"
                         if len(rows) > max_items else ""))
        lines.append("")

        # Markdown table
        header = "| " + " | ".join(format_key(c) for c in display_cols) + " |"
        separator = "| " + " | ".join("---" for _ in display_cols) + " |"
        lines.append(header)
        lines.append(separator)

        for row in display_rows:
            row_line = "| " + " | ".join(
                f"`{format_value(row.get(c, 'N/A'))}`" for c in display_cols
            ) + " |"
            lines.append(row_line)

        if len(rows) > max_items:
            lines.append("")
            lines.append(f"*... and {len(rows) - max_items} more records*")

    elif isinstance(payload, list):
        lines.append(f"**Items: {len(payload)}**")
        lines.append("")
        for i, item in enumerate(payload[:max_items], 1):
            lines.append(f"{i}. `{format_value(item)}`")
        if len(payload) > max_items:
            lines.append(f"\n*... and {len(payload) - max_items} more*")

    elif isinstance(payload, dict):
        flat = flatten_for_display(payload, exclude_set)
        for key, value in flat:
            lines.append(f"- **{key}:** `{value}`")

        # Nested lists as sub-tables
        for k, v in payload.items():
            if isinstance(v, list) and v and isinstance(v[0], dict):
                lines.append("")
                lines.append(f"### {format_key(k)} ({len(v)} items)")
                lines.append("")
                is_sub_table, sub_rows, sub_cols = detect_table_data(v)
                if is_sub_table:
                    sub_cols = [c for c in sub_cols
                                if not should_exclude(c, exclude_set)][:6]
                    header = "| " + " | ".join(
                        format_key(c) for c in sub_cols) + " |"
                    sep = "| " + " | ".join("---" for _ in sub_cols) + " |"
                    lines.append(header)
                    lines.append(sep)
                    for row in v[:max_items]:
                        row_line = "| " + " | ".join(
                            f"`{format_value(row.get(c, ''))}`"
                            for c in sub_cols
                        ) + " |"
                        lines.append(row_line)
    else:
        lines.append(f"`{format_value(payload)}`")

    return "\n".join(lines)


# ============================================================
# MAIN
# ============================================================

# --- Read inputs (XDR injects these variables) ---
raw_json = raw_json  # noqa: F841

try:
    title = title
except NameError:
    title = "API Response"

try:
    max_items = int(max_items)
except (NameError, ValueError, TypeError):
    max_items = 25

try:
    extra_excludes = {k.strip().lower() for k in exclude_keys.split(",")}
except NameError:
    extra_excludes = set()

exclude_set = DEFAULT_EXCLUDE | extra_excludes

# --- Parse JSON ---
try:
    data = json.loads(raw_json) if isinstance(raw_json, str) else raw_json
except (json.JSONDecodeError, TypeError) as e:
    data = {"status": "error", "message": f"Failed to parse JSON: {str(e)}"}

# --- Generate outputs ---
formatted_message = format_plain(data, title, exclude_set, max_items)
slack_message = format_slack(data, title, exclude_set, max_items)
webex_message = format_webex(data, title, exclude_set, max_items)

# --- Extra outputs for workflow conditions ---
_, status_value = detect_status(data)
status_value = status_value or "unknown"

payload = detect_data_payload(data)
if isinstance(payload, list):
    record_count = str(len(payload))
elif isinstance(payload, dict):
    record_count = str(len(payload.keys()))
else:
    record_count = "1"
